def find_pattern(numbers):
    # Check the differences between consecutive elements to find the pattern
    differences = []
    for i in range(1, len(numbers)):
        diff = abs(numbers[i] - numbers[i-1])
        differences.append(diff)

    # Check if the differences are repeating in a consistent manner
    for i in range(1, len(differences)):
        if differences[i] != differences[i-1]:
            return []

    if len(differences) > 1:
        return [numbers[-1] + differences[-1]] * (len(numbers) + 10)
    else:
        return []

