def find_sequels(numbers):
    sequels = []
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            while j == len(numbers):
                n = numbers[j] + 1
                if len(str(n)) <= 3:
                    sequels.append(n)
                else:
                    break
            for k in range(i+1, j):
                while numbers[k] != 0:
                    numbers[k] -= 1

    return " ".join(map(str, sequels))

